<script>
document.addEventListener("DOMContentLoaded", function () {
  const dropdown = document.querySelector(".contents-dropdown");
  const button = document.querySelector(".contents-button");
  const links = document.querySelectorAll(".contents-menu a[href^='#']");
  const appZone = document.querySelector(".app-embed-zone");

  if (!dropdown || !button) return;

  function updateContentsVisibility() {
    if (!appZone) return;

    const dropdownRect = dropdown.getBoundingClientRect();
    const appRect = appZone.getBoundingClientRect();

    const overlaps =
      dropdownRect.bottom > appRect.top &&
      dropdownRect.top < appRect.bottom;

    if (overlaps) {
      dropdown.classList.add("hide-over-app");
      dropdown.classList.remove("is-open");
    } else {
      dropdown.classList.remove("hide-over-app");
    }
  }

  updateContentsVisibility();
  window.addEventListener("scroll", updateContentsVisibility);
  window.addEventListener("resize", updateContentsVisibility);

  button.addEventListener("click", function (event) {
    event.preventDefault();
    event.stopPropagation();

    if (!dropdown.classList.contains("hide-over-app")) {
      dropdown.classList.toggle("is-open");
    }
  });

links.forEach(function (link) {
  link.addEventListener("click", function (event) {
    event.preventDefault();

    const id = this.getAttribute("href").substring(1);
    const target = document.getElementById(id);

    if (target) {
      const offset = 0; 
      const position = target.getBoundingClientRect().top + window.scrollY - offset;

      window.scrollTo({
        top: position,
        behavior: "smooth"
      });

      dropdown.classList.remove("is-open");
    } else {
      console.log("No element found for ID:", id); 
    }
  });
});

  document.addEventListener("click", function (event) {
    if (!dropdown.contains(event.target)) {
      dropdown.classList.remove("is-open");
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") {
      dropdown.classList.remove("is-open");
    }
  });
});
</script>
